import { canonicalSha256 } from '../core/canonical-json.mjs';
import { matchesAny } from './glob.mjs';
export function resolveRules({rules,unit,taskClass,availableArtifacts=[]}){const available=new Set(availableArtifacts);const selected=[];const skipped=[];for(const rule of [...(rules??[])].sort((a,b)=>a.id.localeCompare(b.id))){const fileMatch=(unit.files??[]).some((file)=>matchesAny(file,rule.fileGlobs??['**']));const taskMatch=!rule.taskClasses?.length||rule.taskClasses.includes(taskClass);const missing=(rule.requires??[]).filter((item)=>!available.has(item));if(fileMatch&&taskMatch&&!missing.length)selected.push(rule);else{const reasons=[];if(!fileMatch)reasons.push('file mismatch');if(!taskMatch)reasons.push('task mismatch');if(missing.length)reasons.push(`missing artifacts: ${missing.join(', ')}`);skipped.push({id:rule.id,reason:reasons.join('; ')});}}const payload={selected,skipped};return Object.freeze({...payload,resolutionSha256:canonicalSha256(payload)});}
